// 0x7274e874ca62410a93bd8bf61c69d8045e399c02 (impl behind 0x8004A169...a432)
// solc 0.8.24, viaIR, optimizer 200, shanghai, @openzeppelin/contracts-upgradeable 5.4.0

// --- events to index ---
event Registered(uint256 agentId, string agentURI, address owner);          // NO indexed params
event URIUpdated(uint256 agentId, string newURI, address updatedBy);        // NO indexed params
event MetadataSet(uint256 agentId, string indexed indexedMetadataKey, string metadataKey, bytes metadataValue);
event Transfer(address from, address to, uint256 tokenId);                  // ERC-721
event MetadataUpdate(uint256 _tokenId);                                     // ERC-4906
event BatchMetadataUpdate(uint256 _fromTokenId, uint256 _toTokenId);
event Upgraded(address implementation);                                     // WATCH THIS: UUPS

// --- writes ---
function register() external returns (uint256);
function register(string agentURI) external returns (uint256);
function register(string agentURI, tuple[] metadata) external returns (uint256);
function setAgentURI(uint256 agentId, string newURI) external;
function setMetadata(uint256 agentId, string metadataKey, bytes metadataValue) external;
function setAgentWallet(uint256 agentId, address newWallet, uint256 deadline, bytes signature) external;
function unsetAgentWallet(uint256 agentId) external;

// --- reads ---
function getAgentWallet(uint256 agentId) external view returns (address);
function getMetadata(uint256 agentId, string metadataKey) external view returns (bytes);
function isAuthorizedOrOwner(address spender, uint256 agentId) external view returns (bool);
function getVersion() external pure returns (string);   // returns "2.0.0"
function tokenURI(uint256 tokenId) external view returns (string);
function ownerOf(uint256 tokenId) external view returns (address);
function eip712Domain() external view returns (bytes1,string,string,uint256,address,bytes32,uint256[]);

// NOTE: NO totalSupply(). Not ERC721Enumerable. Calling it REVERTS.

// 0x16e0fa7f7c56b9a767e34b192b51f921be31da34 (impl behind 0x8004BAa1...9b63)

event NewFeedback(
  uint256 agentId, address clientAddress, uint64 feedbackIndex,
  int128 value, uint8 valueDecimals,
  string indexed indexedTag1, string tag1, string tag2,
  string endpoint, string feedbackURI, bytes32 feedbackHash
);  // topic0 = 0x6a4a61743519c9d648a14e6493f47dbe3ff1aa29e7785c96c8326a205e58febc
    // ONLY tag1 is indexed -- agentId is NOT filterable at the log level
event FeedbackRevoked(uint256 agentId, address clientAddress, uint64 feedbackIndex);
event ResponseAppended(uint256 agentId, address clientAddress, uint64 feedbackIndex,
                       address responder, string responseURI, bytes32 responseHash);

function giveFeedback(uint256 agentId, int128 value, uint8 valueDecimals,
                      string tag1, string tag2, string endpoint,
                      string feedbackURI, bytes32 feedbackHash) external;
function revokeFeedback(uint256 agentId, uint64 feedbackIndex) external;
function appendResponse(uint256 agentId, address clientAddress, uint64 feedbackIndex,
                        string responseURI, bytes32 responseHash) external;

function getSummary(uint256 agentId, address[] clientAddresses, string tag1, string tag2)
  external view returns (uint64 count, int128 sum, uint8 decimals);
function readFeedback(uint256 agentId, address clientAddress, uint64 feedbackIndex)
  external view returns (int128, uint8, string, string, bool);
function readAllFeedback(uint256 agentId, address[] clientAddresses, string tag1, string tag2, bool includeRevoked)
  external view returns (address[], uint64[], int128[], uint8[], string[], string[], bool[]);
function getClients(uint256 agentId) external view returns (address[]);
function getLastIndex(uint256 agentId, address clientAddress) external view returns (uint64);
function getIdentityRegistry() external view returns (address);  // -> 0x8004A169...a432
function getVersion() external pure returns (string);            // "2.0.0"

